mapper.select:
SELECT
FROM sample_borrow_info sbi LEFT JOIN sample_borrow_detail sbd ON sbi.ID = sbd.main_id AND sbd.is_deleted = FALSE WHERE ${params.sqlMap.default} AND sbi.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sbi.create_time desc

SELECT
FROM sample_borrow_info sbi LEFT JOIN sample_borrow_detail sbd ON sbi.ID = sbd.main_id AND sbd.is_deleted = FALSE WHERE ${params.sqlMap.default} AND sbi.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sbi.create_time desc

SELECT sbi.approve_status AS tabFlag, COUNT ( * ) AS COUNT FROM sample_borrow_info sbi INNER JOIN sample_borrow_detail sbd ON sbi.ID = sbd.main_id AND sbd.is_deleted = FALSE AND sbd.wait_return_qty > 0 WHERE sbi.is_deleted = FALSE AND sbi.approve_status = 'approve'
${params.permissionSql}
GROUP BY sbi.approve_status UNION ALL SELECT sbi.approve_status AS tabFlag, COUNT ( * ) AS COUNT FROM sample_borrow_info sbi WHERE sbi.is_deleted = FALSE AND sbi.approve_status != 'approve'
${params.permissionSql}
GROUP BY sbi.approve_status

SELECT sbi.ID AS sourceId, sbi.code AS sourceCode, sbi.approve_status AS approveStatus, sbi.borrow_user_id AS returnUserId, sbi.borrow_user_name AS returnUserName, sbi.borrow_dept_id AS returnDeptId, sbi.borrow_dept_name AS returnDeptName, sbi.lend_user_id AS receiverUserId, sbi.lend_user_name AS receiverUserName, sbi.lend_dept_id AS receiverDeptId, sbi.lend_dept_name AS receiverDeptName, sbd.ID AS sourceDetailId, sbd.sku_id AS skuId, sbd.sku_no AS skuNo, sbd.product_name AS productName, COALESCE ( sbd.wait_return_qty, 0 ) AS waitReturnQty, COALESCE ( b.returnedQty, 0 ) AS returnedQty, COALESCE ( sbd.wait_return_qty, 0 ) - COALESCE ( C.returnedQty, 0 ) AS canReturnQty FROM sample_borrow_info AS sbi LEFT JOIN sample_borrow_detail AS sbd ON sbi.ID = sbd.main_id AND sbd.is_deleted = FALSE LEFT JOIN ( SELECT srd.source_detail_id, SUM ( srd.return_qty ) AS returnedQty FROM sample_return_info AS sri LEFT JOIN sample_return_detail AS srd ON sri.ID = srd.main_id AND srd.is_deleted = FALSE WHERE sri.is_deleted = FALSE AND sri.invalid_status = FALSE AND sri.approve_status = 'approve'
AND srd.source_detail_id IN
#{item}
GROUP BY srd.source_detail_id ) AS b ON b.source_detail_id = sbd. ID LEFT JOIN ( SELECT srd.source_detail_id, SUM ( srd.return_qty ) AS returnedQty FROM sample_return_info AS sri LEFT JOIN sample_return_detail AS srd ON sri.ID = srd.main_id AND srd.is_deleted = FALSE WHERE sri.is_deleted = FALSE AND sri.invalid_status = FALSE AND sri.approve_status != 'approve'
AND srd.source_detail_id IN
#{item}
AND sri.id != #{notId}
GROUP BY srd.source_detail_id ) AS C ON C.source_detail_id = sbd.ID WHERE sbi.is_deleted = FALSE AND sbi.invalid_status = FALSE AND sbd.wait_return_qty > 0
AND sbd.ID IN
#{item}
ORDER BY sbi.code

SELECT sbi.ID AS sourceId, sbi.code AS sourceCode, sbd.ID AS sourceDetailId, sbd.sku_id AS skuId, sbd.sku_no AS skuNo, sbd.product_name AS productName, COALESCE ( sbd.borrow_qty, 0 ) AS borrowQty, COALESCE ( sbd.wait_return_qty, 0 ) AS waitReturnQty, COALESCE ( b.returnedQty, 0 ) AS returnedQty, COALESCE ( sbd.wait_return_qty, 0 ) - COALESCE ( C.returnedQty, 0 ) AS canReturnQty, sbd.remark FROM sample_borrow_info AS sbi LEFT JOIN sample_borrow_detail AS sbd ON sbi.ID = sbd.main_id AND sbd.is_deleted = FALSE LEFT JOIN ( SELECT srd.source_detail_id, SUM ( srd.return_qty ) AS returnedQty FROM sample_return_info AS sri LEFT JOIN sample_return_detail AS srd ON sri.ID = srd.main_id AND srd.is_deleted = FALSE WHERE sri.is_deleted = FALSE AND sri.invalid_status = FALSE AND sri.approve_status = 'approve' GROUP BY srd.source_detail_id ) AS b ON b.source_detail_id = sbd. ID LEFT JOIN ( SELECT srd.source_detail_id, SUM ( srd.return_qty ) AS returnedQty FROM sample_return_info AS sri LEFT JOIN sample_return_detail AS srd ON sri.ID = srd.main_id AND srd.is_deleted = FALSE WHERE sri.is_deleted = FALSE AND sri.invalid_status = FALSE AND sri.approve_status != 'approve'
AND sri.id != #{notId}
GROUP BY srd.source_detail_id ) AS C ON C.source_detail_id = sbd.ID WHERE sbi.is_deleted = FALSE AND sbi.invalid_status = FALSE AND sbi.approve_status = 'approve' AND sbd.wait_return_qty > 0 AND sbi.code = #{params.sourceCode}
AND sbd.sku_no IN
#{item}
and sbd.sku_no ILIKE concat('%',#{params.skuNo}::text,'%')
ORDER BY sbi.code

SELECT DISTINCT ON (sbi.ID)
FROM sample_borrow_info sbi LEFT JOIN sample_borrow_detail sbd ON sbi.ID = sbd.main_id AND sbd.is_deleted = FALSE WHERE ${params.sqlMap.default} AND sbi.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sbi.ID desc, sbi.create_time desc, sbd.id
